5: /** Coalesces rapid source events and serializes background graph updates. */
6: export class DebouncedStructuralGraphUpdater {
7:   private readonly changedPaths = new Set<string>();
8:   private timer: ReturnType<typeof setTimeout> | undefined;
9:   private running: Promise<void> = Promise.resolve();
10:   private disposed = false;
11: 
